form-quote.apiDescription:
## Props

```
export type GQuoteProps = {
  /** @default [] */
  fromCurrencies?: Currency[];
  /** @default [] */
  toCurrencies?: Currency[];
  /** @default '' */
  fromAmount?: string;
  /** @default '' */
  toAmount?: string;
  /** @default 'Default' */
  action?: QuoteAction;
  /** @default false */
  isLoading?: boolean;
  /** @default '' */
  errorMessage?: string;
  /** @default '' */
  availableBalance?: string;
  /** @default false */
  singleInput?: boolean;
  /** @default 'Tú envías' */
  fromLabel?: string;
  /** @default 'Tu contacto recibe' */
  toLabel?: string;
  /** @default false */
  isDisabled?: boolean;
  /** @default false */
  disableOriginSelect?: boolean;
  /** @default false */
  disableOriginInput?: boolean;
  /** @default false */
  disableDestinationSelect?: boolean;
  /** @default false */
  disableDestinationInput?: boolean;
  /** @default true */
  showSwap?: boolean;
  /** @default 'Disponible' */
  availableLabel?: string;
  /** @default 'Intercambiar monedas' */
  swapAriaLabel?: string;
  /** @default 'Sin resultados' */
  emptyResultsText?: string;
  /** @default 'Cargar dinero' */
  actionText?: string;
  /** @default null */
  showAction?: boolean | null;
  /** @default undefined */
  fromFlagCode?: FlagCode;
  /** @default undefined */
  toFlagCode?: FlagCode;
  /** @default [] */
  fromAccounts?: QuoteAccount[];
  /** @default [] */
  toAccounts?: QuoteAccount[];
  /** @default '' */
  fromAccountId?: string;
  /** @default '' */
  toAccountId?: string;
  /** @default 'Buscar' */
  accountSearchPlaceholder?: string;
  /** @default 'Cuenta principal' */
  primaryAccountLabel?: string;
  fromCurrency: string;
  toCurrency: string;
}
```

## Events

```
export type GQuoteEvents = {
  "from-input": [value: string];
  "to-input": [value: string];
  "from-blur": [value: string];
  "to-blur": [value: string];
  "from-currency-change": [currency: Currency];
  "to-currency-change": [currency: Currency];
  swap: [payload: { from: string; to: string; fromAmount: string; toAmount: string; fromFlagCode?: FlagCode | undefined; toFlagCode?: FlagCode | undefined; }];
  "from-focus": [];
  "to-focus": [];
  "action-click": [];
  "from-account-change": [account: QuoteAccount];
  "to-account-change": [account: QuoteAccount];
}
```

## Slots

Each slot is typed with the props it passes to its content.

```
export type GQuoteSlots = {
  action: {};
}
```
